rules.pseudocode:
// x[k], y[k]: bars-ago and price of swing-high occurrences k = 0..M-1 (high-side scan)
haveM = foundHighs >= M;
mx = mean(x); my = mean(y);
sxx = sum((x-mx)^2); sxy = sum((x-mx)*(y-my)); syy = sum((y-my)^2);   // centred: shift-invariant
slopeAgo = sxy / sxx;            // price per bar-ago; forward slope = -slopeAgo
r2 = sxy * sxy / (sxx * syy);    // guard syy > 0 and sxx > 0
lineAt(j) = my + slopeAgo * (j - mx);
qual = haveM && sxx > 0 && syy > 0 && el_gt(r2, minR2)
       && el_ge(slopeAgo, minSlopeAtr * atr(atrLength)) && x[0] <= maxAgeBars;
clean = true; for (i = 1; i < x[0]; ++i) if (el_gt(close[i], lineAt(i))) clean = false;
long = qual && clean && el_gt(close[0], lineAt(0));

ok = foundHighs >= M && el_le(maxH - minH, tol * atr);
for (i = 1; i < oldestBarsAgo; ++i) if (el_gt(close[i], maxH + breakTol * atr)) ok = false;
long = ok && el_ge(close[0], maxH + Y * atr);

// per side: centred least squares on (bars-ago, price) of occurrences 0..X-1
slopeHi = -sxyHi / sxxHi; slopeLo = -sxyLo / sxxLo;   // forward slope, price per bar
long = haveHi && haveLo && el_ge(slopeHi, s * atr) && el_ge(slopeLo, s * atr);
